// План specs/invoices.md 2.3 (кейс .qa/tests/invoices/IN-04). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: счёт без имени (TTP Customer) с позицией «QA-AUTO inv-noname-line …»; в конце — Actions → Delete со страницы счёта.
import { test, expect } from '../../fixtures';
import { CLIENT, ROLE, addManualItem, invoiceNameRow, invoiceNumber, openNewInvoiceForm, pickCustomer, removeDocumentAt, stamp } from './invoice-helpers';

test.describe('Счета — пустой Invoice name (#dce958)', () => {
  test('QA-AUTO: saved invoice without a name shows its INV number as the name #dce958 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    const label = `QA-AUTO inv-noname #dce958 ${stamp()}`;
    let invoiceUrl: string | null = null;
    try {
      await openNewInvoiceForm(page);
      await pickCustomer(page, CLIENT);
      await addManualItem(page, { name: `QA-AUTO inv-noname-line ${stamp()}`, price: '1' });
      invoiceUrl = page.url();

      await page.getByRole('button', { name: 'Create Invoice' }).click();
      await expect(page.getByRole('button', { name: 'Create Invoice' })).toHaveCount(0, { timeout: 20_000 });
      invoiceUrl = page.url();
      await expect.poll(() => invoiceNumber(page), { message: 'номер созданного счёта' }).toMatch(/^INV-\d+$/);
      const number = await invoiceNumber(page);

      // Имя = номер обычным текстом, рядом карандаш, без скелетона (коммент программиста — «INV-0001» текстом)
      const row = invoiceNameRow(page);
      await expect(row.getByRole('button', { name: number, exact: true })).toBeVisible();
      await expect(row.getByRole('button', { name: number, exact: true })).toHaveClass(/text-gray-900/);
      await expect(row.getByRole('button', { name: 'Add name', exact: true })).toHaveCount(0);
      await expect(row.locator('.animate-pulse')).toHaveCount(0);
    } finally {
      await removeDocumentAt(page, invoiceUrl, label);
    }
  });
});
